async programOpen(context, template, handle, pid, bounds, layout = false) {
  if (layout) {
    if (!coordinator?.has(context.ownerKey)) return { ok: false, error: "The containing window layout is not ready." };
    const snapshot = coordinator.snapshot(context.ownerKey);
    const existing2 = snapshot?.groups.find((g) => g.tabs.some((t) => t.handle === handle));
    const tab = existing2?.tabs.find((t) => t.handle === handle);
    if (existing2 && tab) return coordinator.command(context.ownerKey, "select", { groupId: existing2.id, tabId: tab.id });
    for (const [page, docked2] of programs) for (const entry22 of [...docked2.values()]) {
      if (entry22.template !== template) continue;
      docked2.delete(entry22.key);
      if (!docked2.size) programs.delete(page);
      await releaseProgram(entry22);
    }
    await coordinator.releaseWindow(handle);
    // Flow is an explicit managed template: reuse its dead slot, never append a duplicate.
    const deadGroup = template === "appflowy" ? snapshot?.groups.find(g => g.tabs.some(t => t.kind === "dormant" && /^(?:AppFlowy|Flow)(?:$| ·)/i.test(t.title || ""))) : null;
    const dead = deadGroup?.tabs.find(t => t.kind === "dormant" && /^(?:AppFlowy|Flow)(?:$| ·)/i.test(t.title || ""));
    if (dead) {
      const reply = await coordinator.command(context.ownerKey, "reconnect", { retainedId: dead.id, handle, pid });
      if (reply.ok) {
        if (deadGroup.selected && deadGroup.selected !== dead.id) await coordinator.command(context.ownerKey, "select", { groupId: deadGroup.id, tabId: deadGroup.selected });
        if (deadGroup.presentation === "minimized") await coordinator.command(context.ownerKey, "presentation", { groupId: deadGroup.id, mode: "minimized" });
        return { ...reply, tabId: dead.id, snapshot: coordinator.snapshot(context.ownerKey) };
      }
      return reply;
    }
    return coordinator.attach(context.ownerKey, handle, pid, snapshot?.groups.find((g) => g.presentation !== "minimized")?.id);
  }

